'use strict';
const $=s=>{const d=document.querySelector('#modal');return(d?.open?d.querySelector(s):null)||document.querySelector(s)},$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const load=(key,alt)=>{try{return JSON.parse(localStorage.getItem('sweetpeeps-'+key))??alt}catch{return alt}};
const save=(key,v)=>{try{localStorage.setItem('sweetpeeps-'+key,JSON.stringify(v))}catch{}};
const DATA=window.STORE_DATA||{products:[],collections:[],currency:'USD'},P=DATA.products,C=DATA.collections;
const pages=window.STORE_PAGES||{},reviews=window.STORE_REVIEWS||[];
let cart=load('cart',[]),wishlist=load('wishlist',[]),compare=load('compare',[]),currency=load('currency','USD');
const byId=id=>P.find(p=>String(p.id)===String(id)),byHandle=h=>P.find(p=>p.handle===h),collection=h=>C.find(c=>c.handle===h);
const image=p=>p?.images?.[0]||'assets/story.png',available=p=>p.variants.some(v=>v.available),price=p=>Math.min(...p.variants.map(v=>v.price));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n)+(currency==='USD'?'':' USD');
const cats=[['Rings','gold-rings'],['Necklaces','dainty-necklaces'],['Earrings','earrings'],['Bracelets','bracelets']];
const support=[['Contact Us','contact-us'],['FAQs','terms-conditions'],['Orders & Exchanges','orders-cancellations'],['Shipping Info','shipping-f-a-q-s'],['Discount Codes','discount-codes'],['Sizing & Care','sizing-care'],['Privacy Policy','privacy'],['Terms & Conditions','terms-conditions-1']];
const productsFor=h=>{if(h==='all')return P;if(h==='gifts-under-30')return P.filter(p=>price(p)>0&&price(p)<=30);if(h==='sale')return P.filter(p=>p.variants.some(v=>v.compare>v.price));if(h==='rings')return P.filter(p=>/ring/i.test(p.title));return(collection(h)?.ids||[]).map(byId).filter(Boolean)};
const pick=(handles,fallback)=>handles.map(byHandle).filter(Boolean).concat(productsFor(fallback)).filter((p,i,a)=>a.findIndex(x=>x.id===p.id)===i).filter(p=>available(p)&&price(p)>0).slice(0,4);
function priceHTML(p){const v=p.variants.find(v=>v.price===price(p))||p.variants[0];return `<span class="price">${money(v.price)}${v.compare>v.price?`<del>${money(v.compare)}</del>`:''}</span>`}
function card(p,withCompare=false){return `<article class="product-card"><div class="product-image"><a href="#product/${p.handle}" aria-label="View ${esc(p.title)}"><img src="${image(p)}" alt="${esc(p.title)}" loading="lazy" width="600" height="600"></a>${!available(p)?'<span class="badge">Sold out</span>':p.variants.some(v=>v.compare>v.price)?'<span class="badge">A sweet find</span>':''}<div class="card-actions"><button data-action="wish" data-id="${p.id}" class="${wishlist.includes(p.id)?'saved':''}" aria-label="${wishlist.includes(p.id)?'Remove from':'Add to'} wishlist: ${esc(p.title)}" aria-pressed="${wishlist.includes(p.id)}">♡</button><button data-action="quick" data-id="${p.id}" aria-label="Quick view ${esc(p.title)}">+</button></div></div><h3 class="product-name"><a href="#product/${p.handle}">${esc(p.title)}</a></h3>${priceHTML(p)}${withCompare?`<label class="compare-select"><input type="checkbox" data-compare="${p.id}" ${compare.includes(p.id)?'checked':''}> Compare</label>`:''}</article>`}
function productSection(title,sub,items,target){return `<section class="wrap section"><div class="section-heading"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div><a class="text-link" href="#collection/${target}">Shop all <span>→</span></a></div><div class="product-grid">${items.map(p=>card(p)).join('')}</div></section>`}
function reviewHTML(r){return `<article class="review"><div class="stars" aria-label="${r.rating} out of 5 stars">${'★'.repeat(Number(r.rating)||5)}</div><blockquote>“${esc(r.body)}”</blockquote><small>${esc(r.name)}${r.verified?' · Verified on original store':''}</small><small>${esc(r.date)}</small>${r.handle?`<a class="review-product" href="#product/${r.handle}">${esc(r.product)}</a>`:''}</article>`}
function homepage(){const best=pick(['princess-throne-ring','cora-tulip-ring','siren-pearl-ring','shimmer-throne-ring'],'best-sellers-1');const newItems=pick(['clover-pearl-hand-chain','serpentine-wrap-ring','solstice-dome-ring','bold-emerald-cut-ring'],'new');const neck=pick(['mother-of-pearl-clover-cross-necklace','margo-celestial-charm-necklace','cordelia-clover-drop-necklace','prescott-lariat-necklace'],'dainty-necklaces');const catProducts=[best[0],neck[1],productsFor('earrings')[0],productsFor('bracelets')[0]];const ring=byHandle('princess-throne-ring')||best[0];const realCommunity=[...best,...neck].filter(p=>p.images.length>1).slice(0,4);const gift=P.find(p=>p.title.includes('Plus One'))||productsFor('travel-case')[0];return `<section class="hero"><div class="hero-copy"><p class="eyebrow">Made for your everyday</p><h1>Little details.<br>Endless sparkle.</h1><p>Jewelry that feels like you. Made to layer, love, and wear on repeat.</p><a class="button" href="#collection/best-sellers-1">Shop Best Sellers</a><br><a class="text-link" href="#collection/new">Explore New Arrivals <span>→</span></a></div><a class="hero-media" href="#product/margo-celestial-charm-necklace" aria-label="Shop the Margo Celestial Charm Necklace"><img class="hero-image" src="assets/p-8650690232478-1.jpg" alt="SweetPeeps Margo Celestial Charm Necklace worn with a white top" width="850" height="1127" fetchpriority="high"><span class="hero-caption"><span>Margo Celestial Charm Necklace</span><span aria-hidden="true">↗</span></span></a></section><div class="wrap category-grid">${cats.map(([title,h],i)=>`<a class="category" href="#collection/${h}"><img src="${image(catProducts[i])}" alt="${title}" width="400" height="350"><span>${title}</span></a>`).join('')}</div>${productSection('Your next everyday favorites','A few pieces you’ll reach for, again and again.',best,'best-sellers-1')}<section class="editorial"><img src="${ring?.images[2]||ring?.images[1]||image(ring)}" alt="SweetPeeps rings styled together" loading="lazy"><div class="editorial-copy"><p class="eyebrow">More sparkle, more you</p><h2>Better together.</h2><p>Mix, match, and layer. Build a ring stack that feels entirely your own.</p><a class="text-link" href="#collection/gold-rings">Find your ring stack <span>→</span></a></div></section>${productSection('Just arrived','New little things to fall in love with.',newItems,'new')}${productSection('Barely there. Always you.','Dainty necklaces, made for your favorite layers.',neck,'dainty-necklaces')}<section class="editorial story"><img src="assets/story.png" alt="Gold jewelry and a blush jewelry box on ivory linen" loading="lazy"><div class="editorial-copy"><p class="eyebrow">Meet SweetPeeps</p><h2>Small details.<br>A little more you.</h2><p>From Los Angeles, with love. Contemporary jewelry at approachable prices, from a team of women who believe in feeling like yourself.</p><a class="text-link" href="#page/about-us">Our story <span>→</span></a></div></section><section class="wrap section"><div class="section-heading"><div><h2>Worn your way</h2><p>Everyday sparkle, styled by you.</p></div><a class="text-link" href="https://www.instagram.com/shopsweetpeeps/" target="_blank" rel="noopener">@shopsweetpeeps ↗</a></div><div class="community-grid">${realCommunity.map((p,i)=>`<a href="#product/${p.handle}"><img src="${p.images[1]}" alt="${esc(p.title)} styling inspiration" loading="lazy"><span>Shop the piece ↗</span></a>`).join('')}</div>${DATA.video?'<div class="brand-film"><video src="assets/brand-film.mp4" controls playsinline preload="none" poster="assets/p-8650690232478-1.jpg" aria-label="Original SweetPeeps brand film"></video><div><p class="eyebrow">The original SweetPeeps film</p><h2>See the sparkle<br>in motion.</h2><p>A closer look at the little details.</p><div class="film-links">'+(DATA.social||[]).slice(0,5).map((url,i)=>'<a class="text-link" href="'+esc(url)+'" target="_blank" rel="noopener">Watch style reel '+(i+1)+' ↗</a>').join('')+'</div></div></div>':''}<p class="community-description">More ways to wear it: <a class="text-link" href="https://www.tiktok.com/@shopsweetpeeps" target="_blank" rel="noopener">Find us on TikTok ↗</a></p></section><section class="wrap section"><div class="section-heading"><h2>A little love from our community</h2><a class="text-link" href="#page/reviews">All reviews →</a></div><div class="reviews-grid">${reviews.filter(r=>r.body.length>25&&r.body.length<180).slice(0,3).map(reviewHTML).join('')}</div></section>${gift?`<section class="gift-strip"><img src="${image(gift)}" alt="${esc(gift.title)}" loading="lazy"><div><p class="eyebrow">For the little things you love</p><h2>Your jewelry’s<br>plus one.</h2><p>Keep your favorites together, at home or on the go. Explore travel cases and gift-ready extras.</p><p class="pdp-note">The original store advertises a free suede case with $50+. Check current eligibility and availability before ordering.</p><a class="text-link" href="#collection/travel-case">Discover the details →</a></div></section>`:''}<section class="wrap section"><div class="section-heading"><h2>Choose your sparkle path</h2><a class="text-link" href="#collections">All collections →</a></div><div class="collection-pills">${[['Shop All','all'],['New Arrivals','new'],['Best Sellers','best-sellers-1'],['Silver Jewelry','silver-jewelry'],['Pendant Necklaces','pendant-necklaces'],['Bags','bags'],['Custom','custom'],['Back in Stock','back-in-stock-1'],['Gifts under $30','gifts-under-30']].map(([t,h])=>`<a class="pill" href="#collection/${h}">${t}</a>`).join('')}</div></section>`}
function footer(){return `<div class="benefits"><div><strong>From Los Angeles</strong><p>Contemporary pieces, personal style</p></div><div><strong>Thoughtfully priced</strong><p>A little luxury for your everyday</p></div><div><strong>Women-led</strong><p>Made to help you feel like you</p></div><div><strong>Here to help</strong><p><a href="#page/orders-cancellations">Orders, exchanges & care</a></p></div></div><section class="newsletter"><div><h2>A little sparkle in your inbox.</h2><p>New pieces, styling notes, and sweet updates.</p></div><form id="newsletter"><label class="sr-only" hidden for="email">Email address</label><input type="email" id="email" name="email" placeholder="Your email address" aria-label="Email address" required><button class="button" type="submit">Join us</button></form></section><div class="wrap"><div class="footer-top"><div class="footer-brand"><a class="wordmark" href="#home">SWEETPEEPS<small>LOS ANGELES</small></a><p>Jewelry for the everyday you.</p><a class="text-link" href="https://www.instagram.com/shopsweetpeeps/" target="_blank" rel="noopener">Instagram ↗</a></div><div class="footer-col"><h3>Shop</h3>${[...cats,['Pendant Necklaces','pendant-necklaces'],['Silver Jewelry','silver-jewelry'],['Bags','bags'],['Travel Cases','travel-case']].map(([t,h])=>`<a href="#collection/${h}">${t}</a>`).join('')}</div><div class="footer-col"><h3>Here to help</h3>${support.slice(0,6).map(([t,h])=>`<a href="#page/${h}">${t}</a>`).join('')}<a href="#account">My Account</a></div><div class="footer-col"><h3>Discover</h3><a href="#page/about-us">Our Story</a><a href="#collection/new">New Arrivals</a><a href="#collection/best-sellers-1">Best Sellers</a><a href="#page/reviews">Customer Reviews</a><a href="#collection/custom">Custom Jewelry</a><a href="#collection/gifts-under-30">Gifts under $30</a><a href="#collections">All Collections</a></div></div><div class="footer-bottom"><span>© 2026 SweetPeeps / SP Inc.</span><a href="#page/privacy">Privacy Policy</a><a href="#page/terms-conditions-1">Terms & Conditions</a><a href="#page/contact-us">Contact</a><span class="currency"><button data-action="region">United States · USD ▾</button></span></div><p class="local-note">Local presentation · Catalog snapshot: September 9, 2026. Live stock, offers and shipping are confirmed on the original store.</p></div>`}
const crumb=(t)=>`<div class="breadcrumbs"><a href="#home">Home</a><span>/</span><span>${esc(t)}</span></div>`;
function mountHome(){document.title='SweetPeeps — Jewelry for the everyday you';document.body.className='page-home';$('#main').innerHTML=homepage()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function updateBag(){cart=cart.filter(x=>byId(x.id)?.variants.some(v=>v.id===x.variant));save('cart',cart);$('#bag-count').textContent=cart.reduce((n,x)=>n+x.qty,0)}
function openModal(html,cls=''){const d=$('#modal');d.className=cls;$('#modal-content').innerHTML=html;if(!d.open)d.showModal()}
function closeModal(){if($('#modal').open)$('#modal').close()}
function menuHTML(){return `<div><strong>Jewelry</strong>${cats.map(([t,h])=>`<a href="#collection/${h}">${t}</a>`).join('')}<a href="#collection/pendant-necklaces">Pendant Necklaces</a></div><div><strong>Your favorites</strong><a href="#collection/new">New Arrivals</a><a href="#collection/best-sellers-1">Best Sellers</a><a href="#collection/silver-jewelry">Silver Jewelry</a><a href="#collection/925-sterling-silver-rings">Silver Rings</a></div><div><strong>Something special</strong><a href="#collection/custom">Custom Jewelry</a><a href="#collection/travel-case">Travel Cases</a><a href="#collection/bags">Bags</a><a href="#collection/gifts-under-30">Gifts under $30</a></div><div><strong>Explore</strong><a href="#collection/back-in-stock-1">Back in Stock</a><a href="#collection/sale">Sale</a><a href="#collections">All Collections</a><a href="#page/reviews">Reviews</a></div>`}
$('#shop-menu').innerHTML=menuHTML();$('#mobile-nav').innerHTML=`<a href="#collection/new">New Arrivals</a><a href="#collection/best-sellers-1">Best Sellers</a>${cats.map(([t,h])=>`<a href="#collection/${h}">${t}</a>`).join('')}<a href="#collections">All Collections</a><a href="#page/about-us">Our Story</a><a href="#wishlist">Wishlist</a><a href="#account">My Account</a><a href="#page/contact-us">Contact</a><a href="#page/reviews">Reviews</a>`;
$('#footer').innerHTML=footer();updateBag();
