function route(){closeModal();$('#mobile-nav').hidden=true;$('#shop-menu').hidden=true;document.body.className='';const bits=location.hash.slice(1).split('/');const type=bits[0]||'home',h=decodeURIComponent(bits.slice(1).join('/'));if(type==='home')mountHome();else if(type==='collection')renderCollection(h);else if(type==='product')renderProduct(h);else if(type==='page')renderPage(h);else if(type==='cart')renderCart();else if(type==='wishlist')renderWishlist();else if(type==='compare')renderCompare();else if(type==='collections')renderCollections();else if(type==='account')renderAccount();else mountHome();window.scrollTo(0,0);updateCompareBar();}
window.addEventListener('hashchange',route);
let listing={handle:'all',query:'',sort:'featured',finish:'',stock:false,max:'',page:1,view:'grid'};
function renderCollection(handle){listing={handle,query:'',sort:handle==='new'?'new':'featured',finish:'',stock:false,max:'',page:1,view:'grid'};const title=handle==='all'?'All jewelry':handle==='gifts-under-30'?'Gifts under $30':handle==='sale'?'Sweet finds on sale':collection(handle)?.title||'Jewelry';document.title=`${title} — SweetPeeps`;$('#main').innerHTML=`<div class="wrap">${crumb(title)}<div class="page-title"><p class="eyebrow">The SweetPeeps collection</p><h1>${esc(title)}</h1><p>Find a little something that feels like you.</p></div><div class="collection-pills">${[['All Jewelry','all'],...cats,['Silver Jewelry','silver-jewelry'],['Gifts under $30','gifts-under-30']].map(([t,h])=>`<a class="pill ${handle===h?'active':''}" href="#collection/${h}">${t}</a>`).join('')}</div><div class="toolbar"><div><button data-action="filters" aria-expanded="false">☷ Filter</button><span id="result-count" role="status"></span></div><div><label>Sort by <select id="sort"><option value="featured">Featured</option><option value="new">Newest arrivals</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="az">Name: A–Z</option><option value="za">Name: Z–A</option></select></label><button class="view-toggle" data-action="view" aria-label="Toggle grid or list view">▦ View</button></div></div><div class="filters" id="filters" hidden><label>Search this collection<input id="collection-query" type="search" placeholder="Name or style"></label><label>Finish<select id="finish"><option value="">All finishes</option><option value="gold">Gold</option><option value="silver">Silver</option><option value="rose">Rose gold</option></select></label><label>Maximum price (USD)<input id="max-price" type="number" min="0" step="1" placeholder="Any"></label><label class="check"><input id="in-stock" type="checkbox"> In stock only</label><button class="text-link" data-action="reset-filters">Clear filters</button></div><div id="collection-grid" class="product-grid collection-grid"></div><div id="pagination" class="pagination"></div></div>`;$('#sort').value=listing.sort;updateListing()}
function matchingProducts(){let items=productsFor(listing.handle).filter(p=>(!listing.query||(p.title+' '+p.tags.join(' ')).toLowerCase().includes(listing.query.toLowerCase()))&&(!listing.finish||(p.title+' '+p.variants.map(v=>v.title).join(' ')).toLowerCase().includes(listing.finish))&&(!listing.stock||available(p))&&(listing.max===''||price(p)<=Number(listing.max)));if(listing.sort==='price-low')items.sort((a,b)=>price(a)-price(b));if(listing.sort==='price-high')items.sort((a,b)=>price(b)-price(a));if(listing.sort==='az')items.sort((a,b)=>a.title.localeCompare(b.title));if(listing.sort==='za')items.sort((a,b)=>b.title.localeCompare(a.title));if(listing.sort==='new')items.sort((a,b)=>b.id-a.id);return items}
function updateListing(){const items=matchingProducts(),total=Math.max(1,Math.ceil(items.length/24));listing.page=Math.min(listing.page,total);$('#result-count').textContent=`${items.length.toLocaleString()} pieces`;$('#collection-grid').className='product-grid collection-grid '+(listing.view==='list'?'list':'');$('#collection-grid').innerHTML=items.length?items.slice((listing.page-1)*24,listing.page*24).map(p=>card(p,true)).join(''):'<div class="empty"><h2>No pieces found</h2><p>Try a different finish, price or search.</p><button class="button secondary" data-action="reset-filters">Clear filters</button></div>';$('#pagination').innerHTML=items.length?`<button data-action="prev" ${listing.page===1?'disabled':''}>← Previous</button><span>Page ${listing.page} of ${total}</span><button data-action="next" ${listing.page===total?'disabled':''}>Next →</button>`:'';}
function safeDescription(html){const template=document.createElement('template');template.innerHTML=html;template.content.querySelectorAll('script,style,iframe,object,embed,meta,link,form,input,button').forEach(n=>n.remove());template.content.querySelectorAll('*').forEach(el=>{for(const a of [...el.attributes]){if(a.name.startsWith('on')||a.name==='style'||a.name==='srcdoc')el.removeAttribute(a.name)}if(el.hasAttribute('href')){const href=el.getAttribute('href');if(!/^(https?:|mailto:|#|\/)/i.test(href))el.removeAttribute('href');else if(href.startsWith('/'))el.setAttribute('href','https://shopsweetpeeps.com'+href)}if(el.tagName==='IMG'){el.removeAttribute('srcset');el.removeAttribute('sizes');el.setAttribute('loading','lazy');if(el.getAttribute('src')?.startsWith('//'))el.setAttribute('src','https:'+el.getAttribute('src'))}});return template.innerHTML}
function productHTML(p,quick=false){const v=p.variants.find(v=>v.available)||p.variants[0],related=reviews.filter(r=>r.handle===p.handle);return `<div class="pdp" data-product="${p.id}"><div class="gallery"><button class="gallery-main" data-action="zoom" data-src="${image(p)}" style="padding:0;width:100%;display:block" aria-label="Enlarge ${esc(p.title)}"><img id="gallery-photo" src="${image(p)}" alt="${esc(p.title)}" width="700" height="700"><span class="zoom-hint">Click to zoom +</span></button><div class="thumbs">${p.images.map((src,i)=>`<button data-action="thumb" data-src="${src}" class="${i?'':'active'}" aria-label="View image ${i+1}"><img src="${src}" alt="${esc(p.title)} — image ${i+1}" loading="lazy"></button>`).join('')}</div></div><div class="product-info"><p class="eyebrow">SweetPeeps · Little things, loved</p><h1>${esc(p.title)}</h1><div id="variant-price" class="price">${money(v.price)}${v.compare>v.price?` <del>${money(v.compare)}</del>`:''}</div>${related.length?`<a class="text-link" href="#page/reviews" style="margin-top:10px">${related.length} review${related.length>1?'s':''} for this piece →</a>`:''}<p id="stock-status" class="stock">${v.available?'Available in catalog snapshot':'Currently sold out'}</p><p class="short-details">A little detail to make every day feel more like you.</p><div class="variant-field"><label for="variant">${p.options.map(o=>esc(o.name)).join(' / ')} <button data-action="size">Size & care guide</button></label><select id="variant" data-product-id="${p.id}">${p.variants.map(x=>`<option value="${x.id}" ${x.id===v.id?'selected':''}>${esc(x.title)}${!x.available?' — Sold out':''}</option>`).join('')}</select></div>${/custom|personal|initial|birth/i.test(p.title)?'<div class="notice">Choose your available option below. For engraving or other personalization requests, check the original product page before ordering.</div>':''}<div class="buy-row"><div class="qty"><button data-action="quantity-minus" aria-label="Decrease quantity">−</button><input id="product-qty" type="number" aria-label="Quantity" min="1" max="20" value="1"><button data-action="quantity-plus" aria-label="Increase quantity">+</button></div><button id="add-to-bag" class="button" data-action="add" data-id="${p.id}" ${v.available?'':'disabled'}>${v.available?'Add to Bag':'Sold Out'}</button></div><button class="text-link" data-action="wish" data-id="${p.id}">${wishlist.includes(p.id)?'Saved to your wishlist':'♡ Save to wishlist'}</button><p class="pdp-note" style="margin-top:20px">Shipping and availability confirmed on the original store. <a href="#page/shipping-f-a-q-s">Shipping details</a> · <a href="#page/orders-cancellations">Exchange policy</a></p>${quick?`<a class="text-link" href="#product/${p.handle}">View full details →</a>`:`<div class="accordion"><details open><summary>The details</summary><div class="product-description">${safeDescription(p.description)}</div></details><details><summary>Shipping & exchanges</summary><div>Domestic orders are dispatched within 1–4 business days according to the store’s shipping page. Current shipping charges and delivery estimates are confirmed by the original store.<br><br>The published policy allows exchanges within 20 days of purchase, in original packaging and condition; it does not accept returns. <a href="#page/orders-cancellations">Read the full policy →</a></div></details><details><summary>Jewelry care</summary><div>Gently wipe with a soft cloth. Follow the material-specific instructions above. For plated pieces, avoid moisture, perfumes and chemicals.<br><a href="#page/sizing-care">Sizing & care guide →</a></div></details><details><summary>Need a little help?</summary><div>Email <a href="mailto:info@shopsweetpeeps.com">info@shopsweetpeeps.com</a>. The store states a response time of up to 48 hours.</div></details></div><p class="pdp-note"><a href="https://shopsweetpeeps.com/products/${p.handle}" target="_blank" rel="noopener">View this piece on the original store ↗</a></p>`}</div></div>`}
function renderProduct(handle){const p=byHandle(handle);if(!p){$('#main').innerHTML=`<div class="wrap empty"><h1>Piece not in this snapshot</h1><p>You can look for it in the full collection or on the original store.</p><a class="button" href="#collection/all">Explore jewelry</a></div>`;return}document.body.className='page-product';document.title=p.title+' — SweetPeeps';let recent=load('recent',[]).filter(id=>id!==p.id);save('recent',[p.id,...recent].slice(0,12));$('#main').innerHTML=`<div class="wrap">${crumb(p.title)}${productHTML(p)}</div>${productSection('A little more to love','Pieces to make it your own.',P.filter(x=>x.id!==p.id&&available(x)&&x.title.toLowerCase().includes(p.title.toLowerCase().includes('ring')?'ring':p.title.toLowerCase().includes('necklace')?'necklace':'bracelet')).slice(0,4),'all')}${recent.length?productSection('Recently admired','',recent.slice(0,4).map(byId).filter(Boolean),'all'):''}<div class="sticky-buy"><div><strong>${money(price(p))}</strong><br><small>${esc(p.title.length>25?p.title.slice(0,25)+'…':p.title)}</small></div><button class="button" data-action="scroll-buy">Choose options</button></div>`}
function selectedVariant(p){const id=Number($('#variant')?.value);return p.variants.find(v=>v.id===id)||p.variants.find(v=>v.available)||p.variants[0]}
function addItem(id,variantId,qty=1){const p=byId(id),v=p?.variants.find(v=>v.id===Number(variantId));if(!v||!v.available)throw Error('This option is unavailable.');if(v.price===0){const paid=cart.reduce((n,x)=>n+(byId(x.id)?.variants.find(y=>y.id===x.variant)?.price||0)*x.qty,0);if(!paid)throw Error('Add a jewelry piece before choosing complimentary packaging.');if(/50\+|plus one/i.test(p.title)&&paid<50)throw Error('This gift requires a jewelry subtotal of at least $50.');qty=1;}if(!Number.isInteger(qty)||qty<1||qty>20)throw Error('Please choose a quantity from 1 to 20.');const line=cart.find(x=>x.variant===v.id);if(line)line.qty=v.price===0?1:Math.min(20,line.qty+qty);else cart.push({id:p.id,variant:v.id,qty});updateBag();toast('Added to your bag');}
function cartHTML(drawer=false){const total=cart.reduce((n,x)=>n+(byId(x.id)?.variants.find(v=>v.id===x.variant)?.price||0)*x.qty,0);if(!cart.length)return `<div class="empty"><p class="eyebrow">Your little collection</p><h2>Your bag is waiting<br>for a little sparkle.</h2><p>Find your next everyday favorite.</p><a class="button" href="#collection/best-sellers-1">Explore Best Sellers</a></div>`;const rows=cart.map(x=>{const p=byId(x.id),v=p.variants.find(v=>v.id===x.variant);return `<article class="cart-row"><a href="#product/${p.handle}"><img src="${image(p)}" alt="${esc(p.title)}"></a><div><h3><a href="#product/${p.handle}">${esc(p.title)}</a></h3><small>${esc(v.title)}</small><div class="qty"><button data-action="cart-minus" data-id="${x.variant}" aria-label="Decrease ${esc(p.title)} quantity">−</button><span>${x.qty}</span><button data-action="cart-plus" data-id="${x.variant}" aria-label="Increase ${esc(p.title)} quantity">+</button></div></div><div><span class="price">${money(v.price*x.qty)}</span><br><button class="remove" data-action="remove" data-id="${x.variant}">Remove</button></div></article>`}).join('');const summary=`<div class="cart-summary"><h2>A sweet little total</h2><div class="summary-line"><span>Subtotal</span><strong>${money(total)}</strong></div><p class="pdp-note">Shipping, taxes and current offers are confirmed by the original store.</p><label for="gift-note" style="font-size:13px">A note for your gift</label><textarea id="gift-note" rows="2" maxlength="300" placeholder="Write a little something…">${esc(load('gift-note',''))}</textarea><small>Your note is saved on this device for your presentation.</small><button class="button" data-action="checkout">Continue on original store ↗</button><small>This is a local shopping preview. Continue to the original store to review your selected items and complete a real purchase. No payment is collected here.</small>${drawer?'<a class="text-link" style="margin-top:18px" href="#cart">View full bag →</a>':''}</div>`;return drawer?`<h2>Your bag <span style="font:16px Arial">(${cart.reduce((n,x)=>n+x.qty,0)})</span></h2>${rows}<div style="margin-top:25px">${summary}</div>`:`<div class="cart-layout"><div>${rows}<a class="text-link" style="margin-top:25px" href="#collection/all">← Keep exploring</a></div>${summary}</div>`}
function renderCart(){document.title='Your Bag — SweetPeeps';$('#main').innerHTML=`<div class="wrap">${crumb('Your bag')}<div class="page-title"><h1>Your little collection.</h1></div>${cartHTML()}</div>`}
function refreshCart(){if($('#modal').open&&$('#modal').classList.contains('drawer'))$('#modal-content').innerHTML=cartHTML(true);else if(location.hash==='#cart')renderCart();updateBag()}
function renderWishlist(){document.title='Your Wishlist — SweetPeeps';const items=wishlist.map(byId).filter(Boolean);$('#main').innerHTML=`<div class="wrap">${crumb('Wishlist')}<div class="page-title"><p class="eyebrow">Keep a little love aside</p><h1>Your wishlist.</h1><p>All the pieces you’ve had your eye on, saved on this device.</p></div>${items.length?`<div class="product-grid section">${items.map(p=>card(p)).join('')}</div>`:'<div class="empty"><h2>Something will catch your eye.</h2><p>Tap the heart on a piece to keep it here.</p><a class="button" href="#collection/all">Discover jewelry</a></div>'}</div>`}
function renderCollections(){document.title='All Collections — SweetPeeps';$('#main').innerHTML=`<div class="wrap">${crumb('Collections')}<div class="page-title"><h1>Choose your sparkle path.</h1><p>Every collection, all in one place.</p></div><div class="all-collections">${[['All Jewelry','all'],['Gifts under $30','gifts-under-30'],...C.map(c=>[c.title,c.handle])].map(([t,h])=>`<a href="#collection/${h}">${esc(t)}<small>${productsFor(h).length} pieces →</small></a>`).join('')}</div></div>`}
function renderCompare(){document.title='Compare Jewelry — SweetPeeps';const items=compare.map(byId).filter(Boolean);$('#main').innerHTML=`<div class="wrap">${crumb('Compare')}<div class="page-title"><h1>A closer look.</h1><p>Compare up to four favorites side by side.</p></div>${items.length?`<div class="compare-table"><table><tr><th>Piece</th>${items.map(p=>`<td><a href="#product/${p.handle}"><img src="${image(p)}" alt="${esc(p.title)}"><h3>${esc(p.title)}</h3></a><button class="text-link" data-action="uncompare" data-id="${p.id}">Remove</button></td>`).join('')}</tr><tr><th>Price</th>${items.map(p=>`<td>${priceHTML(p)}</td>`).join('')}</tr><tr><th>Availability</th>${items.map(p=>`<td>${available(p)?'In catalog stock':'Sold out'}</td>`).join('')}</tr><tr><th>Options</th>${items.map(p=>`<td>${p.options.map(o=>esc(o.name)+': '+o.values.map(esc).join(', ')).join('<br>')}</td>`).join('')}</tr><tr><th>Details</th>${items.map(p=>`<td><div class="product-description">${safeDescription(p.description)}</div></td>`).join('')}</tr></table></div>`:'<div class="empty"><h2>Pick your favorites first.</h2><p>Select Compare under products in a collection.</p><a class="button" href="#collection/all">Explore jewelry</a></div>'}</div>`}
function updateCompareBar(){document.querySelector('.compare-bar')?.remove();if(compare.length&&location.hash!=='#compare'){const d=document.createElement('div');d.className='compare-bar';d.innerHTML=`<span>${compare.length} piece${compare.length>1?'s':''} selected</span><a href="#compare">Compare →</a><button data-action="clear-compare">Clear</button>`;document.body.appendChild(d)}}
function renderAccount(){document.title='Your Account — SweetPeeps';$('#main').innerHTML=`<div class="wrap"><div class="account-panel"><p class="eyebrow">Welcome back</p><h1>Your SweetPeeps world.</h1><p>Sign in on the original store to see your orders, track a delivery or manage your account.</p><a class="button" href="https://shopsweetpeeps.com/account/login" target="_blank" rel="noopener">Sign in / Register ↗</a><p class="pdp-note" style="margin-top:22px">Account access opens securely on shopsweetpeeps.com.</p><div class="button-row" style="justify-content:center;margin-top:30px"><a class="text-link" href="#wishlist">Your local wishlist</a><a class="text-link" href="#page/orders-cancellations">Orders & exchanges</a></div></div></div>`}
function renderPage(h){const page=pages[h];document.title=(page?.title||'SweetPeeps')+' — SweetPeeps';if(h==='reviews'){$('#main').innerHTML=`<div class="wrap">${crumb('Reviews')}<div class="page-title"><p class="eyebrow">Real words from the community</p><h1>Small pieces.<br>Sweet stories.</h1><p>Customer reviews imported from the original store. These are store-wide reviews, with each piece identified below.</p><a class="text-link" href="https://shopsweetpeeps.com/pages/reviews" target="_blank" rel="noopener">See the latest reviews ↗</a></div><div class="reviews-grid section">${reviews.map(reviewHTML).join('')}</div></div>`;return}if(h==='about-us'){$('#main').innerHTML=`<div class="wrap">${crumb('Our story')}</div><section class="editorial story"><img src="assets/story.png" alt="SweetPeeps inspired jewelry still life"><div class="editorial-copy"><p class="eyebrow">From Los Angeles, with love</p><h1>More than<br>a little sparkle.</h1><p>Jewelry to make you feel confident, beautiful, and entirely yourself.</p></div></section><div class="wrap"><article class="prose" style="padding-top:55px"><h2>Meet SweetPeeps</h2>${page?.html||''}<a class="button" href="#collection/all">Find your everyday favorites</a></article></div>`;return}if(!page){$('#main').innerHTML=`<div class="empty"><h1>Let’s find that for you.</h1><a class="button" href="#home">Back to home</a></div>`;return}$('#main').innerHTML=`<div class="wrap">${crumb(page.title)}<div class="policy-layout"><aside class="policy-nav" aria-label="Help topics">${support.map(([t,s])=>`<a class="${h===s?'active':''}" href="#page/${s}">${t}</a>`).join('')}</aside><article class="prose"><h1>${esc(page.title)}</h1>${h==='contact-us'?'<div class="contact-card"><p class="eyebrow">A little help, with love</p><h2>We’re here for you.</h2><p>For product questions, order support and exchanges:</p><a href="mailto:info@shopsweetpeeps.com">info@shopsweetpeeps.com</a><p style="margin-top:20px">The store states a response time of up to 48 hours. Include your order number when asking about an order.</p></div>':''}${page.html}<div class="notice">Policy content is a snapshot of the original store. <a href="${page.source}" target="_blank" rel="noopener">Check the current policy ↗</a></div></article></div></div>`}
function openSearch(){openModal(`<p class="eyebrow">Find your next favorite</p><div class="search-field"><input id="search-input" type="search" placeholder="Try rings, pearls, or a little gold…" aria-label="Search the catalog" autocomplete="off"></div><div class="collection-pills">${cats.map(([t,h])=>`<a class="pill" href="#collection/${h}">${t}</a>`).join('')}</div><div id="search-count" class="pdp-note"></div><div id="search-results" class="search-results"></div>`,'search');$('#search-input').focus();searchResults('')}
function searchResults(q){const all=q.trim()?P.filter(p=>p.title.toLowerCase().includes(q.toLowerCase())):productsFor('best-sellers-1');$('#search-count').textContent=q?`${all.length} pieces found · showing up to 18`:'A few much-loved pieces';$('#search-results').innerHTML=all.length?all.slice(0,18).map(p=>`<a href="#product/${p.handle}"><img src="${image(p)}" alt="${esc(p.title)}" loading="lazy"><h3>${esc(p.title)}</h3>${priceHTML(p)}</a>`).join(''):'<p>No matches yet. Try “ring”, “pearl” or “gold”.</p>'}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a)return;const id=Number(a.dataset.id),p=byId(id);switch(a.dataset.action){case'region':openModal(`<div class="account-panel"><p class="eyebrow">Where you shop</p><h2>A little sparkle, wherever you are.</h2><p>This local catalog uses USD prices. Choose your country and currency on the original store for current regional prices and delivery availability.</p><a class="button" href="https://shopsweetpeeps.com/" target="_blank" rel="noopener">Choose region on original store ↗</a></div>`);break;case'menu':$('#mobile-nav').hidden=!$('#mobile-nav').hidden;a.setAttribute('aria-expanded',!$('#mobile-nav').hidden);break;case'shop-menu':$('#shop-menu').hidden=!$('#shop-menu').hidden;a.setAttribute('aria-expanded',!$('#shop-menu').hidden);break;case'close':closeModal();break;case'search':openSearch();break;case'cart':openModal(cartHTML(true),'drawer');break;case'quick':openModal(productHTML(p,true),'quick');break;case'wish':{wishlist=wishlist.includes(id)?wishlist.filter(x=>x!==id):[...wishlist,id];save('wishlist',wishlist);a.classList.toggle('saved',wishlist.includes(id));a.setAttribute('aria-pressed',wishlist.includes(id));if(!a.closest('.card-actions'))a.textContent=wishlist.includes(id)?'Saved to your wishlist':'♡ Save to wishlist';if(location.hash==='#wishlist')renderWishlist();toast(wishlist.includes(id)?'Saved to your wishlist':'Removed from your wishlist');break}case'filters':$('#filters').hidden=!$('#filters').hidden;a.setAttribute('aria-expanded',!$('#filters').hidden);break;case'reset-filters':listing.query='';listing.finish='';listing.max='';listing.stock=false;listing.page=1;$('#collection-query').value='';$('#finish').value='';$('#max-price').value='';$('#in-stock').checked=false;updateListing();break;case'view':listing.view=listing.view==='grid'?'list':'grid';updateListing();break;case'next':listing.page++;updateListing();$('.toolbar').scrollIntoView({block:'start'});break;case'prev':listing.page=Math.max(1,listing.page-1);updateListing();$('.toolbar').scrollIntoView({block:'start'});break;case'thumb':$('#gallery-photo').src=a.dataset.src;$('.gallery-main').dataset.src=a.dataset.src;$$('.thumbs button').forEach(b=>b.classList.toggle('active',b===a));break;case'zoom':openModal(`<img src="${a.dataset.src}" alt="Jewelry detail enlarged">`,'zoom');break;case'size':openModal(`<div class="prose"><h2>Sizing & care</h2>${pages['sizing-care']?.html||'<p>See each product’s description for its dimensions and material-specific care instructions.</p>'}<a class="text-link" href="https://shopsweetpeeps.com/pages/sizing-care" target="_blank" rel="noopener">View the original size guide ↗</a></div>`);break;case'quantity-minus':$('#product-qty').value=Math.max(1,Number($('#product-qty').value)-1);break;case'quantity-plus':$('#product-qty').value=Math.min(20,Number($('#product-qty').value)+1);break;case'add':try{addItem(id,selectedVariant(p).id,Number($('#product-qty').value));openModal(cartHTML(true),'drawer')}catch(err){toast(err.message)}break;case'scroll-buy':$('#variant').scrollIntoView({block:'center',behavior:'smooth'});$('#variant').focus({preventScroll:true});break;case'cart-minus':{const x=cart.find(x=>x.variant===id);if(x)x.qty--;cart=cart.filter(x=>x.qty>0);refreshCart();break}case'cart-plus':{const x=cart.find(x=>x.variant===id);if(x)x.qty=Math.min(20,x.qty+1);refreshCart();break}case'remove':cart=cart.filter(x=>x.variant!==id);refreshCart();break;case'checkout':{const link='https://shopsweetpeeps.com/cart/'+cart.map(x=>`${x.variant}:${x.qty}`).join(',');openModal(`<div class="account-panel"><p class="eyebrow">One more little step</p><h2>Continue with SweetPeeps.</h2><p>Your chosen items will open on the original store. Please review prices, stock, shipping and any gift offer there before purchasing.</p><a class="button" href="${link}" target="_blank" rel="noopener">Open my bag on SweetPeeps ↗</a><p class="pdp-note" style="margin-top:18px">Your locally saved gift note does not transfer automatically.</p></div>`);break}case'uncompare':compare=compare.filter(x=>x!==id);save('compare',compare);renderCompare();updateCompareBar();break;case'clear-compare':compare=[];save('compare',compare);$$('[data-compare]').forEach(i=>i.checked=false);updateCompareBar();break;}});
document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-compare]')){const id=Number(t.dataset.compare);if(t.checked&&compare.length>=4){t.checked=false;toast('Choose up to four pieces to compare.');return}compare=t.checked?[...new Set([...compare,id])]:compare.filter(x=>x!==id);save('compare',compare);updateCompareBar()}if(t.id==='sort'){listing.sort=t.value;listing.page=1;updateListing()}if(t.id==='finish'){listing.finish=t.value;listing.page=1;updateListing()}if(t.id==='in-stock'){listing.stock=t.checked;listing.page=1;updateListing()}if(t.id==='variant'){const p=byId(t.dataset.productId),v=selectedVariant(p);$('#variant-price').innerHTML=money(v.price)+(v.compare>v.price?` <del>${money(v.compare)}</del>`:'');$('#stock-status').textContent=v.available?'Available in catalog snapshot':'Currently sold out';$('#add-to-bag').disabled=!v.available;$('#add-to-bag').textContent=v.available?'Add to Bag':'Sold Out'}if(t.id==='currency'){currency=t.value;save('currency',currency);toast('Catalog prices are in USD. Other currencies are available on the original store.')}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='search-input')searchResults(t.value);if(t.id==='collection-query'){listing.query=t.value;listing.page=1;updateListing()}if(t.id==='max-price'){listing.max=t.value;listing.page=1;updateListing()}if(t.id==='gift-note')save('gift-note',t.value)});
document.addEventListener('submit',e=>{if(e.target.id==='newsletter'){e.preventDefault();const email=$('#email').value;openModal(`<div class="account-panel"><p class="eyebrow">Stay in the loop</p><h2>A little more SweetPeeps.</h2><p>This preview does not subscribe your email. Visit the original store to join the newsletter and see the current first-order offer.</p><a class="button" href="https://shopsweetpeeps.com/#shopify-section-sections--18956736495774__footer" target="_blank" rel="noopener">Join on the original store ↗</a></div>`);}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
document.addEventListener('click',e=>{if(e.target.closest('a[href^="#"]'))closeModal();if(!e.target.closest('.nav-shop'))$('#shop-menu').hidden=true});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'search_sweetpeeps_catalog',description:'Search the local SweetPeeps catalog snapshot without changing the bag.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:({query})=>{if(typeof query!=='string')throw Error('query must be a string');return P.filter(p=>p.title.toLowerCase().includes(query.toLowerCase())).slice(0,20).map(p=>({id:p.id,title:p.title,price:price(p),currency:'USD',available:available(p),variants:p.variants}))}});document.modelContext.registerTool({name:'get_local_bag',description:'Read the local preview bag. No checkout or purchase occurs.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>cart.map(x=>({...x,title:byId(x.id)?.title}))})}catch{}}
